#[test]
fn max_message_bytes_limits_body_in_bytes() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 4}}));
    let send = |body: &str| json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
    h.ok(send("abcd"));
    h.ok(send("éé"));
    assert_eq!(h.err(send("abcde")), "InvalidParameterValue");
    assert_eq!(h.err(send("éé!")), "InvalidParameterValue");
}

#[test]
fn max_message_bytes_is_checked_before_queue_type_rules() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 2}}));
    let r = json!({"Command": "SendMessage", "QueueName": "q", "Body": "abc", "GroupId": "g"});
    assert_eq!(h.err(r), "InvalidParameterValue");
}

#[test]
fn max_message_bytes_can_change_and_keeps_old_messages() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcdef"}));
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 3}}));
    let got = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(got["Attributes"]["MaxMessageBytes"], 3);
    assert_eq!(got["Counts"]["Visible"], 1);
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcd"})),
        "InvalidParameterValue"
    );
}

#[test]
fn max_message_bytes_range_and_create_idempotence() {
    let mut h = Harness::new();
    for bad in [json!(0), json!(1025), json!("5")] {
        let c = json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": bad}});
        assert_eq!(h.err(c), "InvalidParameterValue");
    }
    let c = |n: u64| json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": n}});
    h.ok(c(10));
    h.ok(c(10));
    assert_eq!(h.err(c(11)), "QueueAlreadyExists");
}
