    assert_eq!(h.err(send_batch(json!(big))), "TooManyEntriesInBatchRequest");
    let bad_ids = [
        json!(5),
        json!({"Body": "x"}),
        json!({"Id": null, "Body": "x"}),
        json!({"Id": 1, "Body": "x"}),
        json!({"Id": "", "Body": "x"}),
        json!({"Id": "a b", "Body": "x"}),
        json!({"Id": "a".repeat(81), "Body": "x"}),
    ];
    for bad in bad_ids {
        assert_eq!(h.err(send_batch(json!([bad.clone()]))), "InvalidBatchEntryId", "{bad}");
    }
    h.ok(send_batch(json!([{"Id": "a".repeat(80), "Body": "x"}])));
    assert_eq!(
        h.err(send_batch(json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "y"}]))),
        "BatchEntryIdsNotDistinct"
    );
    assert_eq!(
        h.err(send_batch(json!([{"Id": "a"}, {"Id": "a"}, 5]))),
        "InvalidBatchEntryId"
    );
    assert_eq!(h.err(send_batch(json!(big.iter().chain(&big).collect::<Vec<_>>()))), "TooManyEntriesInBatchRequest");
}

#[test]
fn batch_request_level_checks_come_first_and_do_nothing() {
    let mut h = setup(json!({}));
    assert_eq!(h.err(json!({"Command": "SendMessageBatch", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "DeleteMessageBatch", "Entries": []})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "SendMessageBatch", "QueueName": "q", "Entries": {}})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "SendMessageBatch", "QueueName": 1, "Entries": []})), "InvalidParameterValue");
    assert_eq!(
        h.err(json!({"Command": "SendMessageBatch", "QueueName": "nope", "Entries": []})),
        "QueueDoesNotExist"
    );
    h.err(send_batch(json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "x"}])));
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts["Visible"], 0);
    assert_eq!(h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}))["MessageId"], "m-1");
}

#[test]
fn delete_batch_handles_each_handle_once() {
    let mut h = setup(json!({}));
    for _ in 0..3 {
        h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    }
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 3}));
    let r = h.ok(delete_batch(json!([
        {"Id": "a", "ReceiptHandle": "r-1"},
        {"Id": "b", "ReceiptHandle": "r-1"},
        {"Id": "c", "ReceiptHandle": "r-99"},
        {"Id": "d"},
        {"Id": "e", "ReceiptHandle": "r-3"},
    ])));
    assert_eq!(r["Successful"], json!([{"Id": "a"}, {"Id": "e"}]));
    let codes: Vec<(&str, &str)> = r["Failed"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| (f["Id"].as_str().unwrap(), f["error"]["code"].as_str().unwrap()))
        .collect();
    assert_eq!(
        codes,
        [
            ("b", "ReceiptHandleExpired"),
            ("c", "ReceiptHandleInvalid"),
            ("d", "MissingParameter"),
        ]
    );
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts, json!({"Visible": 0, "InFlight": 1, "Delayed": 0}));
}
